CREATE TABLE IF NOT EXISTS BillOfMaterials (id TEXT PRIMARY KEY, storeId TEXT NOT NULL, name TEXT NOT NULL, description TEXT, outputProductId TEXT, outputQty REAL NOT NULL DEFAULT 1, unit TEXT NOT NULL DEFAULT 'pcs', active INTEGER NOT NULL DEFAULT 1, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS BOMComponent (id TEXT PRIMARY KEY, bomId TEXT NOT NULL, productId TEXT NOT NULL, qty REAL NOT NULL, unit TEXT NOT NULL DEFAULT 'pcs', notes TEXT);
CREATE TABLE IF NOT EXISTS WorkOrder (id TEXT PRIMARY KEY, storeId TEXT NOT NULL, number TEXT NOT NULL, bomId TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'DRAFT', plannedQty REAL NOT NULL DEFAULT 1, producedQty REAL NOT NULL DEFAULT 0, plannedStart TEXT, actualStart TEXT, completedAt TEXT, notes TEXT, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS WorkOrderMaterial (id TEXT PRIMARY KEY, workOrderId TEXT NOT NULL, productId TEXT NOT NULL, requiredQty REAL NOT NULL, consumedQty REAL NOT NULL DEFAULT 0);
